// Partículas
  const container = document.getElementById('particles');
  for (let i = 0; i < 18; i++) {
    const p = document.createElement('div');
    p.className = 'particle';
    const size = Math.random() * 4 + 2;
    p.style.cssText = `
      width:${size}px; height:${size}px;
      left:${Math.random()*100}%;
      animation-duration:${Math.random()*14+10}s;
      animation-delay:${Math.random()*10}s;
    `;
    container.appendChild(p);
  }

  // Contador animado
  function animateCount(el, target, suffix='') {
    let start = 0;
    const step = Math.ceil(target / 40);
    const timer = setInterval(() => {
      start = Math.min(start + step, target);
      el.textContent = start + suffix;
      if (start >= target) clearInterval(timer);
    }, 40);
  }
  setTimeout(() => {
    animateCount(document.getElementById('stat-dest'), 4);
    animateCount(document.getElementById('stat-pass'), 500, '+');
    animateCount(document.getElementById('stat-anos'), 8);
  }, 800);

  // Scroll reveal nos cards
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        const delay = (e.target.dataset.delay || 0) * 120;
        setTimeout(() => e.target.classList.add('visible'), delay);
        observer.unobserve(e.target);
      }
    });
  }, { threshold: 0.1 });
  document.querySelectorAll('.card').forEach(c => observer.observe(c));

  // Galeria de fotos (placeholder — troque as URLs por fotos reais)
  const galleries = [
    ["data:image/png;base64,"],   // Guarapari
    ["data:image/png;base64,"],    // Cabo Frio
    ["data:image/png;base64,"],       // Angra dos Reis
    ["data:image/png;base64,"],     // Arraial do Cabo
  ];

  document.querySelectorAll('.card-gallery').forEach((gallery, gi) => {
    const imgs = galleries[gi];
    if (!imgs.length) return;

    // Remove placeholder
    gallery.querySelector('.gallery-placeholder').remove();

    let current = 0;
    const dotsEl = gallery.querySelector('.gallery-dots');

    imgs.forEach((src, i) => {
      const img = document.createElement('img');
      img.src = src;
      img.className = i === 0 ? 'active' : '';
      gallery.insertBefore(img, gallery.querySelector('.gallery-btn.prev'));

      const dot = document.createElement('button');
      dot.className = 'gallery-dot' + (i === 0 ? ' active' : '');
      dot.onclick = () => goTo(i);
      dotsEl.appendChild(dot);
    });

    function goTo(idx) {
      gallery.querySelectorAll('img')[current].classList.remove('active');
      gallery.querySelectorAll('.gallery-dot')[current].classList.remove('active');
      current = (idx + imgs.length) % imgs.length;
      gallery.querySelectorAll('img')[current].classList.add('active');
      gallery.querySelectorAll('.gallery-dot')[current].classList.add('active');
    }

    gallery.querySelector('.prev').onclick = () => goTo(current - 1);
    gallery.querySelector('.next').onclick = () => goTo(current + 1);

    setInterval(() => goTo(current + 1), 4000);
  });

  // Formulário
  document.getElementById('contact-form').addEventListener('submit', function(e) {
    e.preventDefault();
    const btn = this.querySelector('.form-submit');
    btn.textContent = 'Enviando...';
    btn.disabled = true;
    setTimeout(() => {
      btn.style.display = 'none';
      const success = document.getElementById('form-success');
      success.style.display = 'flex';
    }, 1200);
  });

function showWip(e) {
    // Deixa links âncora (#) e o botão de fechar funcionarem normalmente
    const tag = e.currentTarget;
    const href = tag.getAttribute('href') || '';
    if (href.startsWith('#') && href.length > 1) return; // âncoras internas ok
    e.preventDefault();
    const overlay = document.getElementById('wip-overlay');
    const box     = document.getElementById('wip-box');
    overlay.style.display = 'flex';
    requestAnimationFrame(() => {
      box.style.transform = 'scale(1)';
      box.style.opacity   = '1';
    });
  }

  function closeWip() {
    const overlay = document.getElementById('wip-overlay');
    const box     = document.getElementById('wip-box');
    box.style.transform = 'scale(0.85)';
    box.style.opacity   = '0';
    setTimeout(() => { overlay.style.display = 'none'; }, 280);
  }

  // Fecha clicando fora
  document.getElementById('wip-overlay').addEventListener('click', function(e) {
    if (e.target === this) closeWip();
  });

  // Fecha com Esc
  document.addEventListener('keydown', e => { if (e.key === 'Escape') closeWip(); });

  // Aplica em todos os botões e links que não sejam âncoras internas
  document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('a.card-btn, button.form-submit, a.nav-cta').forEach(el => {
      el.addEventListener('click', showWip);
    });
  });